// The runners, actually run.
//
// These are shell scripts generated by a TypeScript function, which is
// the worst of both worlds for being sure they work: a unit test that
// matches strings proves the text, not the behaviour, and the e2e
// suite only ever reaches the first ten lines -- the demo pool has no
// AlphaFold3, so every node there exits at "not available here".
//
// So this runs them, with a stand-in for the tutorial's wrapper
// script. What is checked is everything between finding the wrapper
// and the status file: the private directory, the RENAME that
// transfer_output_remaps would have done under condor_submit and does
// not do under DAGMan, the confidence numbers lifted out of the
// archive, and a status file on the failure paths.

import { execFileSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, describe, expect, it } from 'vitest';
import {
  DATA_RUNNER,
  EXIT_NO_AF3,
  EXIT_NO_INPUT,
  INFERENCE_RUNNER,
  buildDataRunner,
  buildInferenceRunner,
  dataStatusFile,
  dataTarball,
  inferenceStatusFile,
  inferenceTarball,
  type RunSpec,
} from './af3';
import { NONE } from './site';

const SPEC: RunSpec = { site: NONE, weights: '/staging/x/alphafold3/af3.bin.zst' };
const TAG = 'Job1_t';

let dirs: string[] = [];
afterEach(() => {
  for (const d of dirs) rmSync(d, { recursive: true, force: true });
  dirs = [];
});

function sandbox(): string {
  const dir = mkdtempSync(join(tmpdir(), 'af3-runner-'));
  dirs.push(dir);
  return dir;
}

/** Run a runner the way its submit file does, and report what happened. */
function run(dir: string, runner: string, outputs: string[]): { code: number; status: unknown } {
  // The submit file creates every declared output before anything
  // else, so a job that dies early is not HELD for a missing file.
  for (const f of outputs) writeFileSync(join(dir, f), '');
  let code = 0;
  try {
    execFileSync('bash', [runner], { cwd: dir, env: { ...process.env, AF3_TAG: TAG } });
  } catch (e) {
    code = (e as { status: number }).status;
  }
  const text = readFileSync(join(dir, outputs[outputs.length - 1]), 'utf8');
  return { code, status: text.trim() ? JSON.parse(text) : undefined };
}

function wrapper(dir: string, name: string, body: string): void {
  writeFileSync(join(dir, name), `#!/bin/bash\n${body}\n`, { mode: 0o755 });
}

describe('the alignment runner', () => {
  const outputs = [dataTarball(TAG), dataStatusFile(TAG)];

  function prepare(): string {
    const dir = sandbox();
    writeFileSync(join(dir, DATA_RUNNER), buildDataRunner(SPEC));
    writeFileSync(join(dir, `${TAG}.fold_input.json`), '{"name":"t"}');
    return dir;
  }

  it('renames the wrapper’s output to the name the next stage globs for', () => {
    const dir = prepare();
    // The real wrapper writes a FIXED data_pipeline.tar.gz, and the
    // inference wrapper looks for *.data_pipeline.tar.gz, which that
    // name does not match.
    wrapper(dir, 'data_pipeline.sh', 'mkdir -p o && cp *.json o/ && tar zcf data_pipeline.tar.gz -C o .');

    const { code, status } = run(dir, DATA_RUNNER, outputs);
    expect(code).toBe(0);
    expect(status).toMatchObject({ stage: 'data', job: TAG, status: 'ok', exit: 0 });
    expect((status as { bytes: number }).bytes).toBeGreaterThan(0);
    // ...and the tarball is under the job's own name, in the directory
    // every node of the workflow shares.
    const listed = execFileSync('tar', ['tzf', join(dir, dataTarball(TAG))], { encoding: 'utf8' });
    expect(listed).toContain('fold_input.json');
  });

  it('gives the wrapper a directory holding only this job’s sequences', () => {
    const dir = prepare();
    // The wrapper moves EVERY *.json beside it into AlphaFold3's input
    // directory. Run in the shared directory it would take the other
    // jobs' sequences and this job's own status file with them.
    writeFileSync(join(dir, 'Job2_other.fold_input.json'), '{"name":"other"}');
    wrapper(dir, 'data_pipeline.sh', 'ls *.json > seen.txt; mkdir -p o && cp *.json o/ && tar zcf data_pipeline.tar.gz -C o .');

    const { code } = run(dir, DATA_RUNNER, outputs);
    expect(code).toBe(0);
    const listed = execFileSync('tar', ['tzf', join(dir, dataTarball(TAG))], { encoding: 'utf8' });
    expect(listed).toContain('fold_input.json');
    expect(listed).not.toContain('Job2_other');
  });

  it('says what happened, and does not retry, when the machine has no AlphaFold3', () => {
    const dir = prepare();
    const { code, status } = run(dir, DATA_RUNNER, outputs);
    expect(code).toBe(EXIT_NO_AF3);
    expect(status).toMatchObject({ status: 'error' });
    expect((status as { message: string }).message).toContain('data_pipeline.sh');
  });

  it('reports the wrapper’s own last words when it fails', () => {
    const dir = prepare();
    wrapper(dir, 'data_pipeline.sh', 'echo "jackhmmer: out of memory" >&2; exit 9');

    const { code, status } = run(dir, DATA_RUNNER, outputs);
    expect(code).toBe(9);
    const s = status as { status: string; message: string; exit: number };
    expect(s.status).toBe('error');
    expect(s.exit).toBe(9);
    expect(s.message).toContain('out of memory');
  });

  it('does not report success when the wrapper produced nothing', () => {
    const dir = prepare();
    wrapper(dir, 'data_pipeline.sh', 'exit 0');

    const { code, status } = run(dir, DATA_RUNNER, outputs);
    expect(code).not.toBe(0);
    expect((status as { message: string }).message).toContain('no alignments');
  });

  it('says so when its sequences did not arrive', () => {
    const dir = sandbox();
    writeFileSync(join(dir, DATA_RUNNER), buildDataRunner(SPEC));
    wrapper(dir, 'data_pipeline.sh', 'exit 0');

    const { code, status } = run(dir, DATA_RUNNER, outputs);
    expect(code).toBe(EXIT_NO_INPUT);
    expect((status as { message: string }).message).toContain('sequence file');
  });
});

describe('the structure runner', () => {
  const outputs = [inferenceTarball(TAG), inferenceStatusFile(TAG)];

  function prepare(withWeights = true): string {
    const dir = sandbox();
    writeFileSync(join(dir, INFERENCE_RUNNER), buildInferenceRunner(SPEC));
    writeFileSync(join(dir, dataTarball(TAG)), 'pretend alignments');
    if (withWeights) writeFileSync(join(dir, 'af3.bin.zst'), 'pretend weights');
    return dir;
  }

  it('brings back the confidence numbers, not just a tarball', () => {
    const dir = prepare();
    mkdirSync(join(dir, 'unused'), { recursive: true });
    wrapper(
      dir,
      'inference_pipeline.sh',
      'mkdir -p af_output/x\n' +
        'printf \'{\\n  "ptm": 0.81,\\n  "iptm": 0.44,\\n  "ranking_score": 0.77\\n}\\n\' > af_output/x/x_summary_confidences.json\n' +
        'tar zcf inference_pipeline.tar.gz -C af_output/x .',
    );

    const { code, status } = run(dir, INFERENCE_RUNNER, outputs);
    expect(code).toBe(0);
    // Read out of the archive the job just made, so the page can show
    // a result rather than a download link.
    expect(status).toMatchObject({ status: 'ok', ranking_score: 0.77, ptm: 0.81, iptm: 0.44 });
  });

  it('succeeds without them rather than guessing', () => {
    const dir = prepare();
    wrapper(dir, 'inference_pipeline.sh', 'mkdir -p o && echo model > o/model.cif && tar zcf inference_pipeline.tar.gz -C o .');

    const { code, status } = run(dir, INFERENCE_RUNNER, outputs);
    expect(code).toBe(0);
    expect(status).toMatchObject({ status: 'ok' });
    expect(status).not.toHaveProperty('ranking_score');
  });

  it('names the weights when they did not arrive', () => {
    const dir = prepare(false);
    wrapper(dir, 'inference_pipeline.sh', 'exit 0');

    const { code, status } = run(dir, INFERENCE_RUNNER, outputs);
    expect(code).toBe(EXIT_NO_INPUT);
    const message = (status as { message: string }).message;
    expect(message).toContain('af3.bin.zst');
    expect(message).toContain('Google DeepMind');
  });

  it('says so when the alignments did not arrive', () => {
    const dir = sandbox();
    writeFileSync(join(dir, INFERENCE_RUNNER), buildInferenceRunner(SPEC));
    writeFileSync(join(dir, 'af3.bin.zst'), 'pretend weights');
    wrapper(dir, 'inference_pipeline.sh', 'exit 0');

    const { code, status } = run(dir, INFERENCE_RUNNER, outputs);
    expect(code).toBe(EXIT_NO_INPUT);
    expect((status as { message: string }).message).toContain('nothing to fold');
  });
});
